import { createHash } from 'node:crypto';
import { existsSync, readFileSync } from 'node:fs';
import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';
import tailwindcss from '@tailwindcss/vite';

// Browsers keep favicons in a cache of their own that ignores normal expiry, so a
// changed icon only shows once its address changes. Each icon link in index.html gets
// a fingerprint of the file (generated by scripts/build-brand-assets.js just before).
const ICON_LINK = /href="\/(favicon-32\.png|icon-192\.png|apple-touch-icon\.png|site\.webmanifest)"/g;
function versionedIcons() {
  return {
    name: 'voicelk-versioned-icons',
    transformIndexHtml(html) {
      return html.replace(ICON_LINK, (link, file) => {
        const path = new URL(`./public/${file}`, import.meta.url);
        if (!existsSync(path)) return link;
        return `href="/${file}?v=${createHash('sha256').update(readFileSync(path)).digest('hex').slice(0, 10)}"`;
      });
    },
  };
}

export default defineConfig({
  plugins: [react(), tailwindcss(), versionedIcons()],
  server: {
    port: 5173,
    // Same-origin in development, so the admin session cookie just works.
    proxy: { '/api': 'http://localhost:5000' },
  },
});
